import {describe,it,expect} from 'vitest'
import {validateLoop,loopExit,loopPosition,loopBytes} from './loop-contract'
const hash='a'.repeat(64)
export const approval=()=>({schema:'harbeat.loop-extension.v1',scope:'normal-playback-lab',producer:'jetson',approved:true,id:hash,implementationSha256:hash,title:'Instrumental',sampleRate:44100,bpm:98,nativeGain:.76,fadeSeconds:.008,startFrame:1673012,lengthFrames:432000,maxCycles:16,source:{trackId:'track-'+ 'a'.repeat(20),runId:'run',masterSha256:hash,reportSha256:hash,vocalSha256:hash,manifestSha256:hash,profileSha256:hash,stemSha256:{drums:hash,bass:hash,other:hash,vocals:hash}},evidence:{sourceVerified:true,producerHost:'jetson',reconstruction:.01,reconstructionLevelDeltaDb:0,loopSeamDb:-30,vocalMaxDb:-60,vocalClear:true,beatErrorMs:20,peak:.8,entryPeak:.8,exitPeaks:[{phaseFrame:216000,peak:.8},{phaseFrame:432000,peak:.8}]}})
describe('independent finite loop contract',()=>{
 it('restores native source at the approved half-loop phase, and at the loop end after complete cycles',()=>{const p=validateLoop(approval());expect(loopExit(p,4,0).sourceFrame).toBe(p.startFrame+p.lengthFrames/2);const e=loopExit(p,4,38);expect(e.atFrame).toBe(4*p.lengthFrames);expect(e.sourceFrame).toBe(p.startFrame+p.lengthFrames);expect(loopPosition(p,11)).toBeCloseTo(p.startFrame/44100+(11%(p.lengthFrames/44100)));expect(loopBytes(p,4)).toBe(loopBytes(p,16))})
 it('fails closed on forged proof, unsafe tail, arbitrary duration and unbounded repeat',()=>{for(const mutate of [(p:any)=>p.evidence.vocalMaxDb=-40,(p:any)=>p.lengthFrames=430000,(p:any)=>p.source.stemSha256.vocals='b'.repeat(64),(p:any)=>p.maxCycles=100,(p:any)=>p.evidence.exitPeaks.pop()]){const p=approval();mutate(p);expect(()=>validateLoop(p)).toThrow()}expect(()=>loopExit(validateLoop(approval()),100,0)).toThrow()})
})
